def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        if hp <= 2 or no_water >= 1:
            return float(min(budget, 70.0))
        return float(min(budget, 35.0))

    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp in alive:
        if opp.get('budget', 0) >= 180:
            rich_opp += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opp += 1
        prev = opp.get('previous_trace', {})
        if prev:
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    units = supply / WATER_REQ
    scarcity = 0
    if units < 2.0:
        scarcity = 2
    elif units < 3.0:
        scarcity = 1

    need = 0
    if hp <= 2 or no_water >= 2:
        need = 3
    elif hp <= 4 or no_water >= 1:
        need = 2
    elif hp <= 6:
        need = 1

    if need >= 3:
        bid = max(82.0, highest_prev + 3.0)
    elif need == 2:
        bid = max(68.0, avg_prev + 2.0, highest_prev * 0.72)
    else:
        if scarcity == 2:
            bid = max(60.0, avg_prev + 1.5)
        elif scarcity == 1:
            bid = max(48.0, avg_prev * 0.7)
        else:
            bid = max(28.0, avg_prev * 0.45)

    if highest_prev >= 140.0 and need <= 1:
        bid *= 0.72
    elif highest_prev >= 110.0 and scarcity == 0 and need == 0:
        bid *= 0.8

    if rich_opp >= 2 and scarcity >= 1 and need >= 1:
        bid += 6.0
    if urgent_opp >= 2 and need == 0:
        bid -= 6.0

    if day >= 8:
        if need >= 2:
            bid += 8.0
        else:
            bid += 3.0

    max_safe = budget
    if need == 0:
        max_safe = min(max_safe, DAILY_SALARY * 0.75)
    elif need == 1:
        max_safe = min(max_safe, DAILY_SALARY * 0.95)

    bid = min(bid, max_safe)
    bid = max(0.0, bid)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_status['budget'], 1.0)

    target_bid = 0.0

    # Survival priority: higher bid if HP is low
    if my_status['hp'] <= 2: 
        target_bid = DAILY_SALARY * 0.98 
    elif my_status['hp'] <= 4: 
        target_bid = DAILY_SALARY * 0.85
    else: 
        target_bid = DAILY_SALARY * 0.70 

    # Adjust bid based on day progression (become more aggressive towards the end)
    if day_context['day'] >= EPISODE_DAYS - 2: 
        target_bid = max(target_bid, DAILY_SALARY * 0.95)
    elif day_context['day'] >= EPISODE_DAYS - 4: 
        target_bid = max(target_bid, DAILY_SALARY * 0.80)

    # Incorporate opponent's previous day bids to be competitive
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        target_bid = max(target_bid, highest_prev_bid + 1.5)

    # Ensure the bid does not exceed current budget
    final_bid = min(my_status['budget'], target_bid)

    # Ensure a minimum bid if budget allows and water is needed
    if final_bid < 1.0 and my_status['budget'] > 0 and my_status['hp'] > 0:
        final_bid = min(my_status['budget'], 1.0)

    return max(0.0, final_bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    prev_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    if my_status['hp'] < 4:
        return min(my_status['budget'], DAILY_SALARY * 0.8)

    if prev_bids:
        max_prev = max(prev_bids)
        if max_prev > DAILY_SALARY * 0.9:
            return min(my_status['budget'], 30.0)
        return min(my_status['budget'], max_prev + 5.0)

    return min(my_status['budget'], 60.0)
